package com.bank.audit.audit;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;

// Append-only writer. Each record's hash chains to the previous record's
// hash, so editing any past record breaks the chain and is detectable.
@Service
public class AuditService {

    private static final Logger log = LoggerFactory.getLogger(AuditService.class);
    private volatile String lastHash = "GENESIS";  // real impl reads from DB

    public synchronized void append(AuditRecord record) {
        String thisHash = sha256(lastHash + record.fingerprint());
        // In production: INSERT INTO audit_log (...) VALUES (...) — INSERT only.
        log.info("AUDIT actor={} outcome={} prevHash={} thisHash={} {}",
                record.getActor(), record.getOutcome(),
                shortHash(lastHash), shortHash(thisHash), record.fingerprint());
        this.lastHash = thisHash;
    }

    private String sha256(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(md.digest(input.getBytes(StandardCharsets.UTF_8)));
        } catch (Exception e) {
            throw new IllegalStateException("hash failed", e);
        }
    }

    private String shortHash(String h) {
        return h.length() > 8 ? h.substring(0, 8) : h;
    }
}
