package com.bank.audit.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Service
public class TransferService {

    private static final Logger log = LoggerFactory.getLogger(TransferService.class);

    // Returns true on success, throws SecurityException when denied.
    public boolean transfer(String actor, String from, BigDecimal amount) {
        // Rajesh can only move money from his own account SAV2001.
        if (!accountOwnedBy(actor, from)) {
            log.warn("Authorization DENIED: {} tried to move from {}", actor, from);
            throw new SecurityException("not account owner");
        }
        log.info("Transfer of {} from {} by {} succeeded", amount, from, actor);
        return true;
    }

    private boolean accountOwnedBy(String actor, String account) {
        return "rajesh".equals(actor) && "SAV2001".equals(account);
    }
}
