package com.bank.audit.audit;

import com.bank.audit.service.TransferService;
import org.slf4j.MDC;
import org.springframework.stereotype.Component;
import java.math.BigDecimal;
import java.time.Instant;

// Centralized wrapper: records the attempt BEFORE acting and the outcome
// AFTER, so denied and failed operations are both captured. In Spring MVC
// this would be a HandlerInterceptor or an @Around aspect; shown here as a
// thin wrapper for a clear, runnable demo.
@Component
public class AuditInterceptor {

    private final TransferService transferService;
    private final AuditService auditService;

    public AuditInterceptor(TransferService transferService, AuditService auditService) {
        this.transferService = transferService;
        this.auditService = auditService;
    }

    public String audited(String actor, String from, BigDecimal amount) {
        String correlationId = MDC.get("correlationId");
        if (correlationId == null) correlationId = "CORR-" + System.nanoTime();

        // BEFORE — record the attempt no matter what happens next.
        auditService.append(AuditRecord.builder()
                .actor(actor).action("TRANSFER").target(from)
                .outcome("ATTEMPT").correlationId(correlationId)
                .timestamp(Instant.now()).build());

        try {
            transferService.transfer(actor, from, amount);
            // AFTER — success.
            auditService.append(record(actor, from, "SUCCESS", correlationId));
            return "APPROVED";
        } catch (SecurityException denied) {
            // AFTER — denied. THIS is the attack signal we must keep.
            auditService.append(record(actor, from, "DENIED", correlationId));
            return "DENIED";
        } catch (RuntimeException failed) {
            auditService.append(record(actor, from, "FAILURE", correlationId));
            return "FAILED";
        }
    }

    private AuditRecord record(String actor, String from, String outcome, String corr) {
        return AuditRecord.builder()
                .actor(actor).action("TRANSFER").target(from)
                .outcome(outcome).correlationId(corr)
                .timestamp(Instant.now()).build();
    }
}
